def choose_move(observation):
    # Defensive getters
    env = observation.get("environment_name", "")
    sx = observation.get("self_position", (0, 0))[0]
    sy = observation.get("self_position", (0, 0))[1]
    ox = observation.get("opponent_position", (0, 0))[0]
    oy = observation.get("opponent_position", (0, 0))[1]

    def move_towards(tx, ty):
        dx = 0
        dy = 0
        if tx > sx:
            dx = 1
        elif tx < sx:
            dx = -1
        if ty > sy:
            dy = 1
        elif ty < sy:
            dy = -1
        return [dx, dy]

    if env == "pursuit_evasion":
        role = observation.get("self_role", "")
        if role == "pursuer":
            target_x, target_y = ox, oy
        else:
            # Move towards corner furthest from opponent
            grid_width = observation.get("grid_width", 1)
            grid_height = observation.get("grid_height", 1)
            corners = [
                [0,0],
                [0, grid_height -1],
                [grid_width -1, 0],
                [grid_width -1, grid_height -1],
            ]
            target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
            target_x, target_y = target
        return move_towards(target_x, target_y)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or []
        if not targets:
            # fallback to opponent position
            return move_towards(ox, oy)
        target = min(targets, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return move_towards(target[0], target[1])

    # Resource gathering
    resources = observation.get("resources") or []
    if resources:
        best_res = min(resources, key=lambda c: abs(c[0] - sx) + abs(c[1] - sy))
        return move_towards(best_res[0], best_res[1])

    # Default: move towards opponent
    return move_towards(ox, oy)

